# ---------------------------------------------------------------------------
# Lab 05 · Inheritance — where every number in this lab comes from.
#
# Nothing here is estimated. The two code variants are generated by the SAME
# generator the course site already uses in assets/js/viz.js (VIZ["duplication"]),
# ported line for line, then written to disk, counted, changed, and EXECUTED.
#
#   python measure.py          -> measured.json  (read by model.js)
# ---------------------------------------------------------------------------
import ast, io, json, pathlib, platform, sys, tempfile, tokenize

# --- the chapter's own lists, assets/js/viz.js:493-494 ----------------------
NAMES = ["Manager", "Engineer", "Intern", "Designer", "Analyst", "Sales", "Support", "Director"]
FIELDS = ["emp_id", "name", "email", "phone", "address", "hire_date",
          "salary", "department", "tax_id", "bank_acc"]

def gen_dup(n, f):
    """Copy-paste: n independent classes. Port of viz.js:496-500."""
    fields = FIELDS[:f]
    return "\n\n".join(
        "class " + name + ":\n"
        "    def __init__(self, " + ", ".join(fields) + ", extra):\n"
        + "\n".join("        self._" + x + " = " + x for x in fields)
        for name in NAMES[:n]
    ) + "\n"

def gen_inh(n, f):
    """Inheritance: one superclass + n subclasses. Port of viz.js:502-507."""
    fields = FIELDS[:f]
    base = ("class Employee:\n"
            "    def __init__(self, " + ", ".join(fields) + "):\n"
            + "\n".join("        self._" + x + " = " + x for x in fields))
    subs = "\n\n".join(
        "class " + name + "(Employee):\n"
        "    def __init__(self, extra, **kw):\n"
        "        super().__init__(**kw)\n"
        "        self._extra = extra"
        for name in NAMES[:n]
    )
    return base + "\n\n" + subs + "\n"

# --- counting: logical lines, via the tokenizer (not a guess) --------------
def loc(src):
    """Non-blank, non-comment physical lines that carry code."""
    live = set()
    for tok in tokenize.generate_tokens(io.StringIO(src).readline):
        if tok.type in (tokenize.NL, tokenize.NEWLINE, tokenize.COMMENT,
                        tokenize.INDENT, tokenize.DEDENT, tokenize.ENDMARKER):
            continue
        live.add(tok.start[0])
    return len(live)

def classes(src):
    """{class name: its exact source segment} — used to diff at class level."""
    tree = ast.parse(src)
    return {node.name: ast.get_source_segment(src, node)
            for node in tree.body if isinstance(node, ast.ClassDef)}

def edit_sites(before, after):
    """Classes whose source actually differs. Measured, not assumed."""
    a, b = classes(before), classes(after)
    return sorted(k for k in b if a.get(k) != b.get(k))

# --- executing: does every subtype really have the new field? -------------
def run(src, probe_field, n):
    """Instantiate every subtype and report which ones expose probe_field."""
    ns = {}
    exec(compile(src, "<generated>", "exec"), ns)          # generated here, not user input
    nfields = len([k for k in FIELDS if "self._" + k + " = " in src.split("class ")[1]])
    ok, missing, err = [], [], None
    for name in NAMES[:n]:
        cls = ns[name]
        args = {f: f.upper() for f in FIELDS[:nfields]} if "Employee" not in src else None
        try:
            if ns.get("Employee") and issubclass(cls, ns["Employee"]):
                obj = cls(extra="X", **{f: f.upper() for f in FIELDS[:nfields]})
            else:
                obj = cls(*[f.upper() for f in FIELDS[:nfields]], "X")
            (ok if hasattr(obj, "_" + probe_field) else missing).append(name)
        except Exception as e:                              # a real failure, captured
            missing.append(name)
            err = type(e).__name__ + ": " + str(e)
    return {"has_field": ok, "missing_field": missing, "error": err}

# --- the measurement -------------------------------------------------------
F0 = 6                      # the chapter's default: 6 shared fields
NEW = FIELDS[F0]            # the 7th field in the chapter's own list -> "salary"
out = {"generator": "port of assets/js/viz.js VIZ[\"duplication\"] (lines 462-540)",
       "python": platform.python_version(), "shared_fields": F0, "added_field": NEW,
       "rows": []}

tmp = pathlib.Path(tempfile.mkdtemp(prefix="oop05_"))
for n in range(2, 9):
    dup_before, dup_after = gen_dup(n, F0), gen_dup(n, F0 + 1)
    inh_before, inh_after = gen_inh(n, F0), gen_inh(n, F0 + 1)
    for tag, src in (("dup", dup_before), ("inh", inh_before)):
        (tmp / f"{tag}_{n}.py").write_text(src, encoding="utf8")

    # the realistic human error: the change applied to every class but the last one
    partial = "\n\n".join(
        list(classes(dup_after).values())[:-1] + [list(classes(dup_before).values())[-1]]) + "\n"

    out["rows"].append({
        "subtypes": n,
        "loc_dup": loc(dup_before),
        "loc_inh": loc(inh_before),
        "edits_dup": len(edit_sites(dup_before, dup_after)),
        "edits_inh": len(edit_sites(inh_before, inh_after)),
        "edited_classes_dup": edit_sites(dup_before, dup_after),
        "edited_classes_inh": edit_sites(inh_before, inh_after),
        "run_dup_complete": run(dup_after, NEW, n),
        "run_inh_complete": run(inh_after, NEW, n),
        "run_dup_missed_one": run(partial, NEW, n),
    })

# the site's current formulas, checked against the measurement
out["formula_check"] = [
    {"subtypes": r["subtypes"],
     "site_loc_dup": r["subtypes"] * (F0 + 2), "measured_loc_dup": r["loc_dup"],
     "site_loc_inh": (F0 + 2) + r["subtypes"] * 3, "measured_loc_inh": r["loc_inh"]}
    for r in out["rows"]]
out["files_written"] = str(tmp)
pathlib.Path("measured.json").write_text(json.dumps(out, indent=1), encoding="utf8")

for r in out["rows"]:
    print(f"N={r['subtypes']}  LOC dup={r['loc_dup']:3d} inh={r['loc_inh']:3d}   "
          f"edits dup={r['edits_dup']} inh={r['edits_inh']}   "
          f"missed-one -> {len(r['run_dup_missed_one']['missing_field'])} stale subtype(s)")
print("\nformula check (site vs measured):")
for c in out["formula_check"]:
    d = "OK " if c["site_loc_dup"] == c["measured_loc_dup"] else "OFF"
    i = "OK " if c["site_loc_inh"] == c["measured_loc_inh"] else "OFF"
    print(f"  N={c['subtypes']}  dup {c['site_loc_dup']:3d} vs {c['measured_loc_dup']:3d} {d}"
          f"   inh {c['site_loc_inh']:3d} vs {c['measured_loc_inh']:3d} {i}")
print("\nthe real failure, N=8, change applied to 7 of 8 classes:")
print(" ", out["rows"][-1]["run_dup_missed_one"]["error"] or "(no exception)")
print("  stale:", out["rows"][-1]["run_dup_missed_one"]["missing_field"])
